import { API_CONTRACT_VERSION, API_DESCRIPTION, API_TITLE } from '@fastfood/contracts';
import type { INestApplication } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule, type OpenAPIObject } from '@nestjs/swagger';

/**
 * The single place the OpenAPI document is defined.
 *
 * The runtime Swagger UI in `main.ts` and the committed
 * `docs/openapi/openapi.json` are generated by the same builder, so they cannot
 * describe the API differently. They used to be built independently, which is
 * how the version string ended up as `0.0.0-phase0` in one and `0.0.0-phase3`
 * in the other while both claimed to be the canonical document.
 */
export function buildOpenApiDocument(app: INestApplication): OpenAPIObject {
  const config = new DocumentBuilder()
    .setTitle(API_TITLE)
    .setDescription(API_DESCRIPTION)
    .setVersion(API_CONTRACT_VERSION)
    .addBearerAuth()
    .addApiKey({ type: 'apiKey', name: 'Idempotency-Key', in: 'header' }, 'Idempotency-Key')
    .build();
  return SwaggerModule.createDocument(app, config);
}
